﻿var builder = DistributedApplication.CreateBuilder(args);

var seq = builder.AddSeq("seq")
                 .ExcludeFromManifest()
                 .WithLifetime(ContainerLifetime.Persistent)
                 .WithEnvironment("ACCEPT_EULA", "Y");

// SQL Server runs in a container, so the sample runs on Windows, macOS, and Linux.
// The SA password is generated by Aspire and persisted in the AppHost's user secrets; the data
// volume and persistent lifetime keep the databases between AppHost runs.
var sqlServer = builder.AddSqlServer("sqlserver")
                       .WithLifetime(ContainerLifetime.Persistent)
                       .WithDataVolume();

var catalogDb = sqlServer.AddDatabase("catalogdb", "Microsoft.eShopOnWeb.CatalogDb");
var identityDb = sqlServer.AddDatabase("identitydb", "Microsoft.eShopOnWeb.Identity");

// Random per-developer JWT signing key shared by both apps, persisted in the AppHost's user secrets
var jwtSigningKey = builder.AddParameter("jwt-signing-key",
    new GenerateParameterDefault { MinLength = 64, Special = false },
    secret: true,
    persist: true);
const string JwtSigningKeyEnvironmentVariable = "Authentication__Jwt__SigningKey";

// The apps read their databases from the "CatalogConnection" and "IdentityConnection" connection strings.
builder
    .AddProject<Projects.PublicApi>(nameof(Projects.PublicApi).ToLower())
        .WithReference(seq)
        .WithReference(catalogDb, "CatalogConnection")
        .WithReference(identityDb, "IdentityConnection")
        .WithEnvironment(JwtSigningKeyEnvironmentVariable, jwtSigningKey)
        .WaitFor(seq)
        .WaitFor(catalogDb)
        .WaitFor(identityDb);

builder
    .AddProject<Projects.Web>(nameof(Projects.Web).ToLower())
        .WithReference(seq)
        .WithReference(catalogDb, "CatalogConnection")
        .WithReference(identityDb, "IdentityConnection")
        .WithEnvironment(JwtSigningKeyEnvironmentVariable, jwtSigningKey)
        .WaitFor(seq)
        .WaitFor(catalogDb)
        .WaitFor(identityDb);

builder.Build().Run();
